import json,hashlib,subprocess,sys,re
from pathlib import Path
root=Path.cwd(); results=root/'Codex Work/Sub-Agents/Results'; lp=results/'financial-ledger.json'; l=json.loads(lp.read_text(encoding='utf-8-sig')); base=l['baseline']; rows=Path(sys.argv[1]).read_text(encoding='utf-8-sig').strip().splitlines()
for row in rows:
 p,methods,reason,tests,recommendations,ids=row.split('|'); data=(root/p).read_bytes(); blob=subprocess.check_output(['git','show',base+':'+p]); assert data.replace(b'\r\n',b'\n')==blob.replace(b'\r\n',b'\n'),p
 n=len(data.decode('utf-8-sig').splitlines()); rec=dict(path=p,baseline=base,sha256=hashlib.sha256(data).hexdigest(),git_blob_sha256=hashlib.sha256(blob).hexdigest(),baseline_comparison='EQUIVALENT_NORMALIZED_LINE_ENDINGS',status='REVIEWED_STATIC_COMPLETE_FILE',reviewed_line_spans=[[1,n]],functionality_and_reasoning=reason,significant_methods=methods,interactions_and_risks=reason,findings=ids.split(',') if ids else [],evidence='Full bounded source read and cross-path static reasoning; no runtime tests/DB writes.',tests_and_evidence=tests,recommendations=recommendations,uncertainties='Static review only; no runtime reproduction or declaration-level semantic coverage claim. Reported leads not independently confirmed unless linked canonical finding says so.')
 l['records']=[x for x in l['records'] if x['path']!=p]+[rec]; dest=root/'Codex Work/Deep-Audit/File-Reports'/(p+'.md'); dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text('# '+p+'\n\n'+'\n\n'.join('**'+k+'**: '+(v if isinstance(v,str) else json.dumps(v)) for k,v in rec.items())+'\n',encoding='utf-8')
reviewed={r['path'] for r in l['records']}; l['remaining']=[r for r in l['remaining'] if r['path'] not in reviewed]; l['reviewed_count']=len(l['records']); l['remaining_count']=len(l['remaining']); assert l['reviewed_count']+l['remaining_count']==l['scope_count']; lp.write_text(json.dumps(l,indent=2),encoding='utf-8')
s=root/'Codex Work/Deep-Audit/Database-and-Finance/financial-summary.md'; t=s.read_text(encoding='utf-8-sig'); t=re.sub(r'Coverage: \d+ complete files statically reviewed of 327 assigned; \d+ explicitly',f"Coverage: {l['reviewed_count']} complete files statically reviewed of 327 assigned; {l['remaining_count']} explicitly",t); s.write_text(t,encoding='utf-8'); print('Checkpoint',l['reviewed_count'],'reviewed',l['remaining_count'],'NOT_ANALYZED')